contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 dummy) public payable {
        require(dummy == dummy);

        uint256 beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool firstReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        bool secondReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = false;
        } else {
            secondReverted = true;
        }

        assert(firstReverted == false && secondReverted == true && c.MinSum() == beforeMinSum);
    }
}

