// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        bool firstReverted;
        try c.Initialized() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        bool secondReverted;
        try c.Initialized() {
            secondReverted = true;
        } catch {
            secondReverted = false;
        }
        assertTrue(firstReverted == false && secondReverted == true && c.MinSum() == beforeMinSum);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
